mapper.select:
SELECT FROM `seckill_activity` sa LEFT JOIN `product_detail` pd ON pd.id = sa.product_detail_id LEFT JOIN `product` p ON p.id = pd.product_id
sa.merchant_id = #{merchantId}
AND sa.status = #{status}
ORDER BY sa.gmt_created DESC

SELECT FROM `seckill_activity` sa LEFT JOIN `product_detail` pd ON pd.id = sa.product_detail_id LEFT JOIN `product` p ON p.id = pd.product_id
sa.status = #{status}
ORDER BY sa.gmt_created DESC

mapper.update:
UPDATE `seckill_activity`
SET status = #{status}, gmt_modified = NOW()
WHERE id = #{id}

UPDATE `seckill_activity`
SET remain_stock = remain_stock - #{quantity}, gmt_modified = NOW()
WHERE id = #{id} AND remain_stock >= #{quantity}

UPDATE `seckill_activity`
SET remain_stock = remain_stock + #{quantity}, gmt_modified = NOW()
WHERE id = #{id}
